var e={topic:`faith-spiritual-life`,lang:`fa`,strings:[{t:`Charlotte Christian خود را «مدرسه‌ای مسیح‌محور و آماده‌ساز دانشگاه» می‌نامد. این مدرسه مستقل است و به هیچ فرقه‌ای وابسته نیست. هر دانش‌آموز هر سال، از Junior Kindergarten تا پایهٔ 12، یک کلاس کتاب‌مقدس می‌گذراند. هر بخش هر هفته یک مراسم نیایش (chapel) دارد.`,of:`e78f96fc`,at:[`charlotte-christian:lead.strong`]},{t:`مدرسه می‌گوید: «مدرسه زیر هدایت، نفوذ یا پشتیبانی هیچ کلیسای خاصی نیست».`,of:`3b304585`,at:[`charlotte-christian:lead.muted`]},{t:`هفتگی`,of:`417cc4ce`,at:[`charlotte-christian:stats[0].value`]},{t:`مراسم نیایش در هر بخش`,of:`bd8a9141`,at:[`charlotte-christian:stats[0].label`]},{t:`Lower School پنجشنبه‌ها، Middle School سه‌شنبه‌ها و Upper School چهارشنبه‌ها، طبق تقویم 2026–27`,of:`fe7bc3fd`,at:[`charlotte-christian:stats[0].note`]},{t:`واحد مطالعات کتاب‌مقدس برای فارغ‌التحصیلی`,of:`0c43c16a`,at:[`charlotte-christian:stats[1].label`]},{t:`یک کلاس کتاب‌مقدس برای هر سالی که دانش‌آموز در Upper School ثبت‌نام است`,of:`fbf979d1`,at:[`charlotte-christian:stats[1].note`]},{t:`کلیسای مسیحی، و بیشتر`,of:`1033fce9`,at:[`charlotte-christian:stats[2].label`]},{t:`«خانواده‌های ما عضو بیش از 130 کلیسای مسیحی گوناگون‌اند»`,of:`71766cd1`,at:[`charlotte-christian:stats[2].note`]},{t:`ساعت خدمت، دورهٔ 2026`,of:`dd23d2b8`,at:[`charlotte-christian:stats[3].label`]},{t:`که این دوره در سال‌های Upper School خود به دست آورد`,of:`d858a35b`,at:[`charlotte-christian:stats[3].note`]},{t:`هر بخش مراسم نیایش هفتگی خود را در تالار مدرسه دارد، و همهٔ مدرسه سالی چهار بار دیگر هم گرد هم می‌آید. والدین مرور مراسم نیایش هر هفته را با ایمیل دریافت می‌کنند.`,of:`b6b4524b`,at:[`charlotte-christian:chapel.headline`]},{t:`مراسم نیایش Lower School`,of:`00c05305`,at:[`charlotte-christian:chapel.entries[0].title`]},{t:`پنجشنبه‌ها، 8:15–8:45 صبح، Alkire Auditorium. «مراسم نیایش هفتگی به رهبری مدیر زندگی روحانی».`,of:`9578beba`,at:[`charlotte-christian:chapel.entries[0].text`]},{t:`سخنرانان فهرست‌شده برای پاییز 2026 شامل مشاور Lower School و مدیر Lower School هستند. در یکی از هفته‌ها، معلمان و دانش‌آموزان داستانی از کتاب دانیال را نمایش دادند.`,of:`ce1d7c82`,at:[`charlotte-christian:chapel.entries[0].muted`]},{t:`مراسم نیایش Middle School`,of:`16378e57`,at:[`charlotte-christian:chapel.entries[1].title`]},{t:`سه‌شنبه‌ها، 9:30–10:05 صبح، Alkire Auditorium. مراسم نیایش در قالب مجموعه‌هایی با نام‌هایی مانند «Blessing Burglars» (دزدان برکت) برگزار می‌شود.`,of:`a497ab45`,at:[`charlotte-christian:chapel.entries[1].text`]},{t:`سخنرانان فهرست‌شده برای 2026 شامل شبان مدرسه، مدیر زندگی روحانی Middle School، معلمان Middle School و یکی از رهبران دانش‌آموزی Upper School هستند. رهبران پرستش مهمان نیز می‌آیند.`,of:`d9ed8570`,at:[`charlotte-christian:chapel.entries[1].muted`]},{t:`مراسم نیایش Upper School`,of:`c9d9a258`,at:[`charlotte-christian:chapel.entries[2].title`]},{t:`چهارشنبه‌ها، 9:25–10:05 صبح، Alkire Auditorium.`,of:`37fdadb0`,at:[`charlotte-christian:chapel.entries[2].text`]},{t:`مراسم‌های اخیر شامل سخنرانی مدیر Upper School و «میزگردی از خانواده‌های Charlotte Christian» دربارهٔ این بوده است که «حرمت نهادن به خدا در مقام یک خانواده چه معنایی دارد».`,of:`798e1179`,at:[`charlotte-christian:chapel.entries[2].muted`]},{t:`مراسم نیایش همهٔ مدرسه`,of:`e2630cbf`,at:[`charlotte-christian:chapel.entries[3].title`,`hickory-grove-christian:chapel.entries[2].title`]},{t:`چهار مراسم در تقویم 2026–27: بازگشت به مدرسه، شکرگزاری، عید قیام (ایستر) و روز ملی دعا، که در فضای باز، در زمین و ورزشگاه مدرسه برگزار می‌شوند.`,of:`fc758c66`,at:[`charlotte-christian:chapel.entries[3].text`]},{t:`دانش‌آموزان سال آخر در ماه مه یک مراسم نیایش فارغ‌التحصیلی (Baccalaureate Service) نیز دارند.`,of:`ea028f36`,at:[`charlotte-christian:chapel.entries[3].muted`]},{t:`KnightLight Worship`,of:`38ca8c7e`,at:[`charlotte-christian:chapel.entries[4].title`]},{t:`گروه پرستش Lower School. «دانش‌آموزان پایه‌های 3 و 4 می‌توانند در آزمون ورودی شرکت کنند». این گروه چهارشنبه‌ها پس از مدرسه تمرین می‌کند و «در این نیم‌سال چند بار پرستش را در مراسم نیایش Lower School» رهبری می‌کند.`,of:`800f648f`,at:[`charlotte-christian:chapel.entries[4].text`]},{t:`uKnight Worship`,of:`a9fb8cb7`,at:[`charlotte-christian:chapel.entries[5].title`]},{t:`یک گروه پرستش دانش‌آموزی از «خوانندگان، نوازندگان و دانش‌آموزان فنی پایه‌های 9-12 که در طول سال پرستش را در مراسم نیایش رهبری می‌کنند». این یک درس افتخاری (honors) با آزمون ورودی است، نیم واحد دارد و می‌تواند برای الزام هنرهای زیبا حساب شود.`,of:`164eb926`,at:[`charlotte-christian:chapel.entries[5].text`]},{t:`والدین می‌شنوند چه چیزی تعلیم داده شده است.`,of:`30cb3d72`,at:[`charlotte-christian:chapel.note.strong`]},{t:`سه مدیر زندگی روحانی هر هفته ایمیل Chapel Recap (مرور مراسم نیایش) را می‌فرستند، همراه با فهرست پخشی از «سرودهایی که این هفته در مراسم نیایش خواندیم».`,of:`e6d128ad`,at:[`charlotte-christian:chapel.note.text`]},{t:`هر مراسم نیایش با همان دعای برکت پایان می‌یابد، برگرفته از Micah 6:8. روزها و ساعت‌های مراسم نیایش طبق تقویم 2026–27 مدرسه است. در برخی هفته‌ها مراسم نیایش برگزار نمی‌شود.`,of:`898d5f14`,at:[`charlotte-christian:chapel.note.muted`]},{t:`کتاب‌مقدس هر سال، از Junior Kindergarten تا پایهٔ 12، یک کلاس الزامی است. در اینجا می‌بینید هر پایه چه می‌خواند، و چهار واحدی که دانش‌آموز Upper School برای فارغ‌التحصیلی لازم دارد کدام است.`,of:`2ac4ec61`,at:[`charlotte-christian:classes.headline`]},{t:`«مطالعهٔ کتاب‌مقدس بخشی الزامی از برنامهٔ درسی است که از Junior Kindergarten آغاز می‌شود و تا پایهٔ 12 ادامه دارد».`,of:`a011b44b`,at:[`charlotte-christian:classes.intro.text`]},{t:`«در همهٔ کلاس‌ها از ترجمهٔ English Standard Version کتاب‌مقدس استفاده می‌شود». خانواده‌ها کتاب‌مقدس را می‌خرند؛ این کتاب در فهرست لوازم مدرسه برای پایه‌های 1–12 آمده است.`,of:`ca8c90ba`,at:[`charlotte-christian:classes.intro.muted`]},{t:`Lower School`,of:`0921a0ca`,at:[`charlotte-christian:classes.groups[0].name`]},{t:`درس‌های روزانهٔ کتاب‌مقدس`,of:`733a59bd`,at:[`charlotte-christian:classes.groups[0].tally`]},{t:`Junior Kindergarten`,of:`5ee6535c`,at:[`charlotte-christian:classes.groups[0].rows[0].label`]},{t:`«قهرمانان ایمان، محبت خدا به همه، حقیقت کلام خدا»`,of:`b20811bb`,at:[`charlotte-christian:classes.groups[0].rows[0].detail`]},{t:`Kindergarten`,of:`68541d89`,at:[`charlotte-christian:classes.groups[0].rows[1].label`]},{t:`«مروری بر کتاب‌مقدس»`,of:`3ee57c76`,at:[`charlotte-christian:classes.groups[0].rows[1].detail`]},{t:`پایهٔ 1`,of:`20673dd7`,at:[`charlotte-christian:classes.groups[0].rows[2].label`]},{t:`«از آفرینش تا سرزمین موعود»`,of:`54566fbf`,at:[`charlotte-christian:classes.groups[0].rows[2].detail`]},{t:`پایهٔ 2`,of:`21673f6a`,at:[`charlotte-christian:classes.groups[0].rows[3].label`]},{t:`«انجیل‌ها»`,of:`105465d2`,at:[`charlotte-christian:classes.groups[0].rows[3].detail`]},{t:`پایهٔ 3`,of:`226740fd`,at:[`charlotte-christian:classes.groups[0].rows[4].label`]},{t:`«اسرائیل»`,of:`53429d22`,at:[`charlotte-christian:classes.groups[0].rows[4].detail`]},{t:`پایهٔ 4`,of:`1b6735f8`,at:[`charlotte-christian:classes.groups[0].rows[5].label`]},{t:`«اعمال رسولان و کلیسای اولیه». دانش‌آموزان پایهٔ چهارم همچنین «یک درس مقدماتی دفاعیات مسیحی می‌گذرانند» (یعنی یاد می‌گیرند ایمان را توضیح دهند و از آن دفاع کنند).`,of:`5497d699`,at:[`charlotte-christian:classes.groups[0].rows[5].detail`]},{t:`Middle School`,of:`15441234`,at:[`charlotte-christian:classes.groups[1].name`,`hickory-grove-christian:classes.groups[1].name`]},{t:`هر سال یک کلاس کتاب‌مقدس، به‌اضافهٔ خواندن روزانهٔ کتاب‌مقدس`,of:`4b6fc13e`,at:[`charlotte-christian:classes.groups[1].tally`]},{t:`Bible 5`,of:`672446e6`,at:[`charlotte-christian:classes.groups[1].rows[0].label`]},{t:`نبوت دربارهٔ مسیح: «مطالعه‌ای در کتاب پیدایش»`,of:`67866b7d`,at:[`charlotte-christian:classes.groups[1].rows[0].detail`]},{t:`Bible 6`,of:`66244553`,at:[`charlotte-christian:classes.groups[1].rows[1].label`]},{t:`آماده‌سازی برای مسیح: «مطالعه‌ای در عهد عتیق، که با خروج آغاز می‌شود و با 400 سال سکوت پایان می‌یابد».`,of:`72467c36`,at:[`charlotte-christian:classes.groups[1].rows[1].detail`]},{t:`Bible 7`,of:`652443c0`,at:[`charlotte-christian:classes.groups[1].rows[2].label`]},{t:`نقشهٔ مسیح: «مروری کلی بر عهد جدید».`,of:`6acb1671`,at:[`charlotte-christian:classes.groups[1].rows[2].detail`]},{t:`Bible 8`,of:`74245b5d`,at:[`charlotte-christian:classes.groups[1].rows[3].label`]},{t:`شخص مسیح: زندگی و تعلیم عیسی «آن‌گونه که به شکلی یگانه در انجیل یوحنا عرضه شده است».`,of:`29554636`,at:[`charlotte-christian:classes.groups[1].rows[3].detail`]},{t:`Upper School`,of:`bfabeb69`,at:[`charlotte-christian:classes.groups[2].name`]},{t:`برای فارغ‌التحصیلی 4 واحد مطالعات کتاب‌مقدس`,of:`c9c95bce`,at:[`charlotte-christian:classes.groups[2].tally`]},{t:`Old Testament Survey`,of:`6b2cd411`,at:[`charlotte-christian:classes.groups[2].rows[0].label`,`hickory-grove-christian:classes.groups[2].rows[0].label`]},{t:`الزامی برای سال اول.`,of:`389bafe0`,at:[`charlotte-christian:classes.groups[2].rows[0].detail`]},{t:`New Testament Survey`,of:`15a0fcf0`,at:[`charlotte-christian:classes.groups[2].rows[1].label`,`hickory-grove-christian:classes.groups[2].rows[1].label`]},{t:`الزامی برای سال دوم.`,of:`b9ac76f8`,at:[`charlotte-christian:classes.groups[2].rows[1].detail`]},{t:`Christian Theology`,of:`3a8071fd`,at:[`charlotte-christian:classes.groups[2].rows[2].label`]},{t:`الزامی برای سال سوم. «دانش‌آموزان با تاریخ کلیسا از دورهٔ عهد جدید تا نهضت اصلاح دینی آشنا می‌شوند».`,of:`5056d764`,at:[`charlotte-christian:classes.groups[2].rows[2].detail`]},{t:`World Religions`,of:`a0cf6333`,at:[`charlotte-christian:classes.groups[2].rows[3].label`]},{t:`الزامی برای سال سوم. این درس «بررسی نقادانهٔ ادیان باستانی، ادیان شرقی (از جمله هندوئیسم و بودیسم)، یهودیت و اسلام» است.`,of:`ff42b6fe`,at:[`charlotte-christian:classes.groups[2].rows[3].detail`]},{t:`Apologetics and Cultural Engagement`,of:`6b124f9d`,at:[`charlotte-christian:classes.groups[2].rows[4].label`]},{t:`الزامی برای سال آخر. نیم‌سال اول به دفاعیات مسیحی می‌پردازد. نیم‌سال دوم به «بنیادهای کتاب‌مقدسی و الهیاتی برای تعامل با فرهنگ» می‌پردازد.`,of:`05c1557f`,at:[`charlotte-christian:classes.groups[2].rows[4].detail`]},{t:`دانش‌آموزی که دیرتر به مدرسه می‌آید هم کتاب‌مقدس می‌خواند.`,of:`567deb60`,at:[`charlotte-christian:classes.note.strong`]},{t:`«دانش‌آموزان باید در هر سالی که در Charlotte Christian School ثبت‌نام هستند یک کلاس کتاب‌مقدس را بگذرانند. اگر دانش‌آموزی در سال آخر پذیرفته شود، باید هر دو کلاس کتاب‌مقدس سال سوم و سال آخر را بگذراند».`,of:`91bce979`,at:[`charlotte-christian:classes.note.text`]},{t:`دانش‌آموزان همچنین می‌توانند با امتیاز ویژه در رشتهٔ کتاب‌مقدس، فلسفه و دین فارغ‌التحصیل شوند. شرایط آن شامل معدل (GPA) 3.89 در کتاب‌مقدس، مشارکت فعال در یک کلیسای محلی و مصاحبه با گروه کتاب‌مقدس است.`,of:`2ce95422`,at:[`charlotte-christian:classes.note.muted`]},{t:`هر بخش در پاییز برنامه‌ای ویژهٔ ایمان و دوستی دارد. پایه‌های 5–12 به کوهستان‌های کارولینای شمالی می‌روند، و هزینهٔ آن بخشی از شهریه است.`,of:`beed9505`,at:[`charlotte-christian:retreats.headline`]},{t:`Lower School: Camp S.L.A.M.`,of:`99a07ae0`,at:[`charlotte-christian:retreats.cells[0].title`]},{t:`«همهٔ دانش‌آموزان Lower School در یک روز کامل از فعالیت‌های Camp S.L.A.M. (Spiritual Life and Meaning، یعنی زندگی روحانی و معنا) شرکت خواهند کرد». این روز شامل بازی‌های گروهی و «ستایش، پرستش و مطالعه» است. سخنران پاییز 2026 مدیر زندگی روحانی Lower School بود. پایهٔ 4 روز جداگانه‌ای برای رهبری و تیم‌سازی دارد.`,of:`d5744e60`,at:[`charlotte-christian:retreats.cells[0].text`]},{t:`Middle School: Carolina Point`,of:`f2a7a675`,at:[`charlotte-christian:retreats.cells[1].title`]},{t:`«همهٔ دانش‌آموزان، به‌عنوان بخشی حیاتی از تجربهٔ Middle School، در اردوی روحانی سالانهٔ Carolina Point شرکت می‌کنند»؛ این اردو در یک مرکز اردویی Young Life «بیرون از Brevard, N.C.» برگزار می‌شود. موضوع پاییز 2026 «The Rejoice Choice» (انتخاب شادی) بود. هر نشست بازی، موسیقی پرستشی و یک سخنران دارد، و شب‌ها در کلبه‌ها تأمل روحانی برگزار می‌شود.`,of:`1f0cbfe9`,at:[`charlotte-christian:retreats.cells[1].text`]},{t:`Upper School: Windy Gap`,of:`fd6412c8`,at:[`charlotte-christian:retreats.cells[2].title`]},{t:`مدرسه می‌گوید «از همهٔ دانش‌آموزان خواسته می‌شود در اردوی روحانی سالانهٔ Windy Gap شرکت کنند»؛ این اردو در یک مرکز اردویی Young Life «بیرون از Asheville, N.C.» برگزار می‌شود. موضوع پاییز 2026 «Transformed by Christ» (دگرگون‌شده به دست مسیح) بود. پس از هر یک از چهار نشست پرستشی، «Cabin Time, Reflection, and Sharing» (وقت کلبه، تأمل و در میان گذاشتن) برگزار می‌شود. دانش‌آموزان سال آخر یک روز زودتر می‌روند.`,of:`0b4405fb`,at:[`charlotte-christian:retreats.cells[2].text`]},{t:`مشمول شهریه:`,of:`adfa710e`,at:[`charlotte-christian:retreats.note.strong`]},{t:`«اردوهای روحانی Carolina Point و Windy Gap (اردوی دوروزهٔ زندگی روحانی Middle School و Upper School) و گردش‌های علمی».`,of:`e5d1ff85`,at:[`charlotte-christian:retreats.note.text`]},{t:`«این اردوها فقط با پشتیبانی والدین داوطلب ممکن می‌شوند».`,of:`ea0f66e6`,at:[`charlotte-christian:retreats.note.muted`]},{t:`جایی که دانش‌آموزان در گروه‌های کوچک‌تر دربارهٔ ایمان گفت‌وگو می‌کنند: گروه‌های پیش از مدرسه، تأمل روحانی هنگام ناهار، گروه‌های راهنما (advisory) و رهبران دانش‌آموزی.`,of:`49db66b0`,at:[`charlotte-christian:groups.headline`]},{t:`گروه‌های DIG (Discipleship In Groups، یعنی شاگردسازی در گروه)`,of:`e8091e48`,at:[`charlotte-christian:groups.entries[0].title`]},{t:`گروه‌ها در بخشی از هر نیم‌سال «صبح‌های چهارشنبه پیش از مدرسه از ساعت 7:10-7:35 صبح گرد هم می‌آیند». «این گروه‌ها را دانش‌آموزان داوطلب Upper School با کمک اعضای هیئت آموزشی Middle School رهبری خواهند کرد».`,of:`adce9425`,at:[`charlotte-christian:groups.entries[0].text`]},{t:`ناهار و تأمل روحانی`,of:`88ba61b5`,at:[`charlotte-christian:groups.entries[1].title`]},{t:`مدیر زندگی روحانی Middle School هر هفته یک گفت‌وگوی هنگام ناهار را برای پسران پایهٔ 8 رهبری می‌کند. گروه‌های دیگر شامل «Dodgeball & Devotions» (بازی وسطی و تأمل روحانی) برای پسران پایه‌های 5–7 و یک گروه تأمل روحانی دختران است.`,of:`765d22c7`,at:[`charlotte-christian:groups.entries[1].text`]},{t:`پادشاهی‌ها و گروه‌های راهنما`,of:`e9e85801`,at:[`charlotte-christian:groups.entries[2].title`]},{t:`«Six kingdoms, one king» (شش پادشاهی، یک پادشاه). هر دانش‌آموز Middle School به یکی از شش گروهی می‌پیوندد «که در طول سال به‌طور منظم گرد هم می‌آیند». گروه‌های راهنما (advisory) مطالعهٔ کتاب‌مقدس برگزار می‌کنند، و دانش‌آموزان پایهٔ هشتم می‌توانند در یک Kingdom Council (شورای پادشاهی) برای «زندگی روحانی و دانش‌آموزی» خدمت کنند.`,of:`aaa1b13a`,at:[`charlotte-christian:groups.entries[2].text`]},{t:`مطالعهٔ کتاب‌مقدس در Upper School`,of:`a456d99e`,at:[`charlotte-christian:groups.entries[3].title`]},{t:`والدین و معلمان می‌توانند از طریق مدیر زندگی روحانی Upper School «یک مطالعهٔ کتاب‌مقدس برای دانش‌آموزان Upper School» را رهبری کنند.`,of:`7bcf1ba1`,at:[`charlotte-christian:groups.entries[3].text`]},{t:`صفحه‌های مدرسه نمی‌گویند این گروه‌ها چه زمانی تشکیل می‌شوند.`,of:`c5b18629`,at:[`charlotte-christian:groups.entries[3].muted`]},{t:`رهبران دانش‌آموزی`,of:`e60ca716`,at:[`charlotte-christian:groups.entries[4].title`]},{t:`Spiritual Life Prefect (نمایندهٔ ارشد زندگی روحانی) یکی از نه رهبر دانش‌آموزی سال آخر است. این نمایندگان ارشد در مراسم نیایش سخن می‌گویند و دعا می‌کنند، و داوطلبان Upper School گروه‌های DIG را در Middle School رهبری می‌کنند.`,of:`bcb5af25`,at:[`charlotte-christian:groups.entries[4].text`]},{t:`همایش زندگی روحانی`,of:`0a7d311a`,at:[`charlotte-christian:groups.entries[5].title`]},{t:`در روزهای همایش، «سخنرانان ویژه برای زمانی از تعلیم و گفت‌وگوی متمرکز به مدرسه دعوت می‌شوند».`,of:`265c7d69`,at:[`charlotte-christian:groups.entries[5].text`]},{t:`مأموریت مدرسه، پنج ارزش بنیادین آن و اعتقادنامهٔ ده‌ماده‌ای آن، به بیان خود مدرسه.`,of:`ef08810f`,at:[`charlotte-christian:beliefs.headline`]},{t:`«Charlotte Christian School مدرسه‌ای مسیح‌محور و آماده‌ساز دانشگاه است که دانش‌آموزان را مجهز می‌کند و پرورش می‌دهد تا حقیقت کتاب‌مقدس و یادگیری را به‌طور مؤثر در زندگی روزانهٔ خود درهم بیامیزند و برای مسیح بر فرهنگ اثر بگذارند».`,of:`aed901a1`,at:[`charlotte-christian:beliefs.mission`]},{t:`خدا را محبت کن`,of:`aefdea87`,at:[`charlotte-christian:beliefs.values[0].name`]},{t:`مهربانی نشان بده`,of:`6dca795d`,at:[`charlotte-christian:beliefs.values[1].name`]},{t:`با فروتنی گام بردار`,of:`0d4f9943`,at:[`charlotte-christian:beliefs.values[2].name`]},{t:`در پی برتری باش`,of:`93d0e213`,at:[`charlotte-christian:beliefs.values[3].name`]},{t:`حقیقت را بجوی`,of:`635804ac`,at:[`charlotte-christian:beliefs.values[4].name`]},{t:`هیچ کلیسای واحدی مدرسه را اداره نمی‌کند.`,of:`4eed29f4`,at:[`charlotte-christian:beliefs.note.strong`]},{t:`«اعضای هیئت امنا، هیئت آموزشی و دانش‌آموزان از فرقه‌ها و آیین‌های گوناگون‌اند. مدرسه زیر هدایت، نفوذ یا پشتیبانی هیچ کلیسای خاصی نیست».`,of:`62ae84e0`,at:[`charlotte-christian:beliefs.note.text`]},{t:`آیهٔ محوری سال 2026–27 این است: Philippians 4:4-7.`,of:`2f879cf3`,at:[`charlotte-christian:beliefs.note.muted`]},{t:`«ما ایمان داریم که خدا وجودی یگانه است – بی‌نهایت عادل، حکیم، نیکو، مهربان و قدوس – و از ازل تا ابد در سه شخص وجود دارد: پدر، پسر و روح‌القدس. او آفرینندهٔ حاکم مطلق جهان است و با مشیت خود هرآنچه را ساخته است نگاه می‌دارد و بر آن فرمان می‌راند».`,of:`353df0da`,at:[`charlotte-christian:beliefs.articles[0]`]},{t:`«ما ایمان داریم که عیسی مسیح، پسر خدا، کاملاً خدا و کاملاً انسان است، و او قوم خود را با زندگی، مرگ و رستاخیز خویش از گناهشان نجات می‌دهد، و اکنون به‌واسطهٔ کلام و روح خود بر کلیسای خویش و بر جهان فرمانروایی می‌کند».`,of:`6b2bb59b`,at:[`charlotte-christian:beliefs.articles[1]`]},{t:`«ما ایمان داریم که روح‌القدس به گناهکاران تولد تازه می‌بخشد، در ایمانداران ساکن است و آنان را توانا می‌سازد تا زندگی خداپسندانه‌ای داشته باشند و عطایای روحانی‌ای را که او به ایشان داده است به کار گیرند».`,of:`98e462e3`,at:[`charlotte-christian:beliefs.articles[2]`]},{t:`«ما ایمان داریم که کتب مقدس عهد عتیق و عهد جدید، کلام الهام‌شده، خطاناپذیر و عاری از خطای خداست و مرجع نهایی ما در امور تعلیم و عمل است».`,of:`bf248a55`,at:[`charlotte-christian:beliefs.articles[3]`]},{t:`«ما ایمان داریم که گناهکاران به فیض و از راه ایمان، بر پایهٔ کار به‌انجام‌رسیدهٔ مسیح (مرگ و رستاخیز او) پارسا شمرده می‌شوند و این زندگی را به قدرت خدا می‌زیند».`,of:`78d0acc5`,at:[`charlotte-christian:beliefs.articles[4]`]},{t:`«ما ایمان داریم که خدا مردمانی را از میان تمامی نژاد بشر فرا می‌خواند تا به پسر او، عیسی مسیح، ایمان آورند و عضو بدن او، یعنی کلیسا، شوند. آنان که به عیسی در مقام خداوند و نجات‌دهنده ایمان دارند، تا بازگشت عیسی از برکات خدا و از مشارکت با یکدیگر در جماعت‌های ایمان بهره‌مندند».`,of:`6246805c`,at:[`charlotte-christian:beliefs.articles[5]`]},{t:`«ما ایمان داریم که انسان، مرد و زن، به صورت خدا آفریده شد، اما بر اثر نافرمانی آدم و حوا در گناه سقوط کرد. در نتیجهٔ این سقوط، همهٔ مردم گناهکار به دنیا می‌آیند و به نجات نیاز دارند».`,of:`d8bf7734`,at:[`charlotte-christian:beliefs.articles[6]`]},{t:`«ما ایمان داریم که ازدواج رابطه‌ای مبتنی بر عهد است که خدا آن را برای یک مرد و یک زن آفریده است. رابطهٔ جنسی هدیه‌ای از سوی خداست و جایگاه شایستهٔ آن تنها در چارچوب ازدواج است».`,of:`e1e3a547`,at:[`charlotte-christian:beliefs.articles[7]`]},{t:`«ما ایمان داریم که عیسی مسیح، پسر خدا، بازخواهد گشت تا تمامی آفرینش را نو سازد و بر زندگان و مردگان داوری کند».`,of:`fe82762c`,at:[`charlotte-christian:beliefs.articles[8]`]},{t:`«ما ایمان داریم که آموزش مسیحی مشارکتی است میان دانش‌آموزان، هیئت آموزشی و والدین، که برای دانش‌آموزان فرصتی فراهم می‌کند تا درس‌ها و فعالیت‌های فوق‌برنامه را از دریچهٔ جهان‌بینی کتاب‌مقدسی و در حضور هیئت آموزشی‌ای که مسیح را حرمت می‌نهد بیاموزند و تجربه کنند».`,of:`2ed3e072`,at:[`charlotte-christian:beliefs.articles[9]`]},{t:`آنچه صفحه‌های عمومی مدرسه دربارهٔ ایمان می‌گویند، هنگام درخواست و پس از ثبت‌نام، و آنچه ناگفته می‌گذارند.`,of:`2700b011`,at:[`charlotte-christian:families.headline`,`hickory-grove-christian:families.headline`]},{t:`هنگام درخواست`,of:`fbc4b036`,at:[`charlotte-christian:families.groups[0].name`,`hickory-grove-christian:families.groups[0].name`]},{t:`پرسش‌های ایمانی از دانش‌آموز`,of:`e7858d01`,at:[`charlotte-christian:families.groups[0].rows[0].label`]},{t:`متقاضیان پایه‌های 5–12 پرسش‌نامه‌ای را با دست پر می‌کنند. این پرسش‌نامه دربارهٔ «فعالیت‌های روحانی و/یا مرتبط با کلیسا» می‌پرسد و می‌گوید: «رابطهٔ خود را با عیسی مسیح شرح دهید».`,of:`13953c35`,at:[`charlotte-christian:families.groups[0].rows[0].detail`]},{t:`مصاحبه با خانواده`,of:`94e34996`,at:[`charlotte-christian:families.groups[0].rows[1].label`,`hickory-grove-christian:families.groups[0].rows[1].label`]},{t:`هر خانواده با «یکی از اعضای تیم رهبری ما» دیدار می‌کند تا «اهداف خود را برای گام بعدی در مسیر تحصیلی دانش‌آموزتان در میان بگذارید».`,of:`47169ee7`,at:[`charlotte-christian:families.groups[0].rows[1].detail`]},{t:`ایمان خود پدر یا مادر`,of:`df592ad8`,at:[`charlotte-christian:families.groups[0].rows[2].label`,`hickory-grove-christian:families.groups[0].rows[4].label`]},{t:`صفحه‌های عمومی نمی‌گویند که آیا پدر یا مادر باید مسیحی باشد یا به کلیسا برود.`,of:`592818ab`,at:[`charlotte-christian:families.groups[0].rows[2].detail`]},{t:`معرفی‌نامه از شبان`,of:`cd83f059`,at:[`charlotte-christian:families.groups[0].rows[3].label`,`hickory-grove-christian:families.groups[0].rows[0].label`]},{t:`در مراحل یا فهرست‌های بازبینی منتشرشدهٔ درخواست، چنین چیزی فهرست نشده است.`,of:`34654847`,at:[`charlotte-christian:families.groups[0].rows[3].detail`]},{t:`امضای اعتقادنامه`,of:`d7d8e80b`,at:[`charlotte-christian:families.groups[0].rows[4].label`]},{t:`در مراحل منتشرشدهٔ درخواست فهرست نشده است.`,of:`19d3e804`,at:[`charlotte-christian:families.groups[0].rows[4].detail`]},{t:`پس از ثبت‌نام`,of:`d9033401`,at:[`charlotte-christian:families.groups[1].name`,`hickory-grove-christian:families.groups[1].name`]},{t:`Family Agreement Form`,of:`56281385`,at:[`charlotte-christian:families.groups[1].rows[0].label`]},{t:`«هم والدین و هم دانش‌آموزان باید Back-to-School Form آنلاین، از جمله Family Agreement Form و Responsible Use Policy، را در myCCS بخوانند و به‌صورت دیجیتال امضا کنند». (این‌ها فرم بازگشت به مدرسه، فرم توافق‌نامهٔ خانواده و سیاست استفادهٔ مسئولانه هستند.) خود فرم در سایت عمومی نیست.`,of:`9cdbb748`,at:[`charlotte-christian:families.groups[1].rows[0].detail`]},{t:`کلاس کتاب‌مقدس`,of:`6f74c399`,at:[`charlotte-christian:families.groups[1].rows[1].label`,`hickory-grove-christian:families.groups[1].rows[0].label`]},{t:`هر سال الزامی است، از Junior Kindergarten تا پایهٔ 12.`,of:`a97a83b2`,at:[`charlotte-christian:families.groups[1].rows[1].detail`]},{t:`اردوهای روحانی`,of:`6e3383f9`,at:[`charlotte-christian:families.groups[1].rows[2].label`]},{t:`در Middle School، «همهٔ دانش‌آموزان شرکت می‌کنند». در Upper School، «از همهٔ دانش‌آموزان خواسته می‌شود شرکت کنند».`,of:`914f06ef`,at:[`charlotte-christian:families.groups[1].rows[2].detail`]},{t:`رفتار دانش‌آموز`,of:`e448eab0`,at:[`charlotte-christian:families.groups[1].rows[3].label`]},{t:`پرسش‌نامهٔ پایه‌های 5–12 این‌گونه پایان می‌یابد: «می‌دانم که باید به این مقررات پایبند باشم و همیشه مسیح را حرمت نهم». Honor Code (منشور شرافت) مدرسه شبانه‌روز و در تمام سال برقرار است.`,of:`270396a5`,at:[`charlotte-christian:families.groups[1].rows[3].detail`]},{t:`مشارکت با والدین`,of:`253a65fc`,at:[`charlotte-christian:families.groups[1].rows[4].label`]},{t:`اعتقادنامه آموزش مسیحی را «مشارکتی میان دانش‌آموزان، هیئت آموزشی و والدین» می‌نامد.`,of:`42b2acae`,at:[`charlotte-christian:families.groups[1].rows[4].detail`]},{t:`حضور در مراسم نیایش`,of:`bf92e599`,at:[`charlotte-christian:families.groups[1].rows[5].label`,`hickory-grove-christian:families.groups[1].rows[3].label`]},{t:`صفحه‌های عمومی نمی‌گویند که آیا مراسم نیایش الزامی است یا نه.`,of:`889f792d`,at:[`charlotte-christian:families.groups[1].rows[5].detail`,`hickory-grove-christian:families.groups[1].rows[3].detail`]},{t:`معلمان و کارکنان باید در این ایمان شریک باشند.`,of:`84aea924`,at:[`charlotte-christian:families.note.strong`,`hickory-grove-christian:families.note.strong`]},{t:`«همهٔ کسانی که برای استخدام درخواست می‌دهند باید مایل باشند در انجام روزانهٔ وظایف خود مسیح را خدمت کنند و از اعتقادنامهٔ ما کاملاً پشتیبانی کنند».`,of:`b779f756`,at:[`charlotte-christian:families.note.text`]},{t:`مدرسه Family Handbook (راهنمای خانواده)، Honor Code و فرم درخواست آنلاین خود را پشت صفحهٔ ورود خانواده‌ها نگه می‌دارد، نه در سایت عمومی‌اش.`,of:`122d7c31`,at:[`charlotte-christian:families.note.muted`]},{t:`مدرسه خدمت را بخشی از ایمان می‌داند. دانش‌آموزان در تمام سال به سازمان‌های غیرانتفاعی محلی خدمت می‌کنند، و دانش‌آموزان Upper School می‌توانند در دورهٔ Winterim به سفرهای بشارتی بپیوندند.`,of:`e01e46c3`,at:[`charlotte-christian:service.headline`]},{t:`روز خدمت همهٔ مدرسه`,of:`233e085e`,at:[`charlotte-christian:service.entries[0].title`]},{t:`در بهار 2026 مدرسه همراه با Servants with a Heart «79,056 وعدهٔ غذا بسته‌بندی کرد».`,of:`06b1ea3b`,at:[`charlotte-christian:service.entries[0].text`]},{t:`Operation Christmas Child`,of:`c21f19dc`,at:[`charlotte-christian:service.entries[1].title`]},{t:`هدف پاییز 2026 «بسته‌بندی 1,850 جعبهٔ کفش» تا زمان مراسم نیایش شکرگزاری بود. همکاران نام‌بردهٔ دیگر عبارت‌اند از The Odd Sock، Bright Blessings، Roof Above و Harvest Center.`,of:`83d1f787`,at:[`charlotte-christian:service.entries[1].text`]},{t:`Kingdom Impact Day`,of:`e47ad8fe`,at:[`charlotte-christian:service.entries[2].title`]},{t:`در بهار 2026 «شش سازمان غیرانتفاعی محلی دربارهٔ مأموریت‌های خود سخن گفتند» و دانش‌آموزان Middle School شنوندهٔ آنان بودند. در برنامه‌ای جداگانه در Middle School برای گردآوری مدادشمعی، «98,484 مدادشمعی» جمع شد.`,of:`c375240b`,at:[`charlotte-christian:service.entries[2].text`]},{t:`سفرهای بشارتی Winterim`,of:`a2547bb4`,at:[`charlotte-christian:service.entries[3].title`]},{t:`«Upper School در طول سال، از جمله در دورهٔ Winterim، فرصت‌های گوناگونی برای سفرهای بشارتی محلی، منطقه‌ای و بین‌المللی فراهم می‌کند». فهرست 2027 شامل یک هفتهٔ Serve Charlotte و سفرهایی با SCORE International، Rancho El Camino و Samaritan’s Feet است.`,of:`583ae11a`,at:[`charlotte-christian:service.entries[3].text`]},{t:`ساعت‌های خدمت از پایهٔ ششم آغاز می‌شود.`,of:`e7835585`,at:[`charlotte-christian:service.note.strong`]},{t:`«از پایهٔ ششم، دانش‌آموزان تشویق می‌شوند هر سال ساعت خدمت به دست آورند».`,of:`b080f66b`,at:[`charlotte-christian:service.note.text`]},{t:`صفحه‌های مدرسه شمار ساعت‌ها را برای هر پایه نمی‌گویند.`,of:`47443ecb`,at:[`charlotte-christian:service.note.muted`]},{t:`هر بخش مدیر زندگی روحانی خود را دارد. مدرسه همچنین یک شبان مدرسه، یک هماهنگ‌کنندهٔ خدمت و یک هماهنگ‌کنندهٔ پرستش را فهرست می‌کند.`,of:`ce5f769a`,at:[`charlotte-christian:staff.headline`]},{t:`مدیر زندگی روحانی Lower School`,of:`164a935d`,at:[`charlotte-christian:staff.people[0].role`]},{t:`مدیر زندگی روحانی Middle School، معلم کتاب‌مقدس Middle School`,of:`6e6cbd6a`,at:[`charlotte-christian:staff.people[1].role`]},{t:`مدیر زندگی روحانی Upper School`,of:`0c132c42`,at:[`charlotte-christian:staff.people[2].role`]},{t:`شبان مدرسه`,of:`a4b30e91`,at:[`charlotte-christian:staff.people[3].role`]},{t:`معلم پخش برنامه و فیلم Upper School، هماهنگ‌کنندهٔ خدمت`,of:`c6474b3e`,at:[`charlotte-christian:staff.people[4].role`]},{t:`هماهنگ‌کنندهٔ هنرهای زیبا و پرستش`,of:`d987057b`,at:[`charlotte-christian:staff.people[5].role`]},{t:`معلم کتاب‌مقدس Upper School، سرپرست گروه کتاب‌مقدس`,of:`27b58135`,at:[`charlotte-christian:staff.people[6].role`]},{t:`از مدیر زندگی روحانی بخش فرزندتان آغاز کنید.`,of:`b6411b3b`,at:[`charlotte-christian:staff.note.strong`]},{t:`پنج معلم کتاب‌مقدس دیگر در فهرست کارکنان مدرسه آمده‌اند.`,of:`645d41b5`,at:[`charlotte-christian:staff.note.muted`]},{t:`مطالعهٔ کتاب‌مقدس، گروه‌های دعا و ایمیل‌های هفتگی که مدرسه برای والدین و پدربزرگ‌ها و مادربزرگ‌ها برگزار می‌کند.`,of:`af457c9d`,at:[`charlotte-christian:parents.headline`]},{t:`ایمیل‌هایی که به خانه می‌رسد`,of:`5601fdb3`,at:[`charlotte-christian:parents.entries[0].title`]},{t:`یک Chapel Recap از مدیران زندگی روحانی، و یادداشتی در روزهای دوشنبه از رئیس مدرسه «با یک اندیشهٔ کوتاه روحانی و چند درخواست دعا برای همهٔ مدرسه».`,of:`188b61b8`,at:[`charlotte-christian:parents.entries[0].text`]},{t:`مطالعهٔ کتاب‌مقدس بانوان Haverim`,of:`aed144bd`,at:[`charlotte-christian:parents.entries[1].title`]},{t:`«چهارشنبه از 12:15-2:15 بعدازظهر، یا سه‌شنبه از طریق Zoom از 7:30-8:30 شب». برای «مادران، مادربزرگ‌ها، مادران دانش‌آموختگان و کارکنان» آزاد است. مطالعهٔ 2026–27 کتاب رومیان است.`,of:`5a3d57c7`,at:[`charlotte-christian:parents.entries[1].text`]},{t:`Parents in Prayer`,of:`ca4f5668`,at:[`charlotte-christian:parents.entries[2].title`]},{t:`پنجشنبه‌ها، 8:00–9:30 صبح در مدرسه، با یک نشست مجازی حدوداً ماهی یک بار. «والدین دعاگو به‌طور منظم برای پسران یا دختران پایهٔ فرزندشان دعا می‌کنند».`,of:`839ff8ec`,at:[`charlotte-christian:parents.entries[2].text`]},{t:`Men’s Power Hour`,of:`68cdfc78`,at:[`charlotte-christian:parents.entries[3].title`]},{t:`«برای مردان CCS»، یک نشست صبحگاهی ماهانه بیرون از مدرسه.`,of:`1a6be535`,at:[`charlotte-christian:parents.entries[3].text`]},{t:`Books and Fellowship`,of:`0bed32bd`,at:[`charlotte-christian:parents.entries[4].title`]},{t:`«برای بانوان CCS»، ماهانه از 8-9:15 صبح در یک خانهٔ شخصی. (نام آن یعنی کتاب و مشارکت.)`,of:`65856cef`,at:[`charlotte-christian:parents.entries[4].text`]},{t:`Romans 12 Gatherings`,of:`a94dd44c`,at:[`charlotte-christian:parents.entries[5].title`]},{t:`برای همهٔ جامعهٔ مدرسه آزاد است، برای گفت‌وگو دربارهٔ «تنوع، تعلق، و فرمان عیسی به زیستن در یگانگی و آشتی با یکدیگر».`,of:`28908133`,at:[`charlotte-christian:parents.entries[5].text`]},{t:`Knight to Knight`,of:`7ef8970a`,at:[`charlotte-christian:parents.entries[6].title`]},{t:`خانواده‌های دانش‌آموزان Lower School و Middle School با دورهٔ سال آخر همراه می‌شوند تا دانش‌آموزان سال آخر را در آخرین سالشان «تشویق کنند، برایشان دعا کنند و برکتشان دهند».`,of:`32740259`,at:[`charlotte-christian:parents.entries[6].text`]},{t:`هر پدر و مادری عضو Parent Teacher Fellowship (انجمن والدین و معلمان) است.`,of:`1eb6ea9d`,at:[`charlotte-christian:parents.note.strong`]},{t:`یکی از کارهای آن «پشتیبانی حیاتی با دعا برای همهٔ جنبه‌های جامعهٔ مدرسه» است.`,of:`dfbbcd1a`,at:[`charlotte-christian:parents.note.text`]},{t:`ده پرسش برای همراه بردن به بازدید از مدرسه. هر پرسش به چیزی می‌پردازد که صفحه‌های عمومی مدرسه بی‌پاسخ می‌گذارند یا به دو شکل می‌گویند.`,of:`d45f86d9`,at:[`charlotte-christian:ask.headline`]},{t:`آیا برای پذیرفته شدن فرزند، پدر یا مادر باید مسیحی باشد یا عضو کلیسایی باشد؟`,of:`a0e1e94d`,at:[`charlotte-christian:ask.questions[0]`,`hickory-grove-christian:ask.questions[0]`]},{t:`Family Agreement Form (فرم توافق‌نامهٔ خانواده) از والدین و دانش‌آموزان می‌خواهد با چه چیزهایی موافقت کنند؟ آیا می‌توانیم پیش از درخواست آن را بخوانیم؟`,of:`f2ef1a03`,at:[`charlotte-christian:ask.questions[1]`]},{t:`در پاسخ دانش‌آموز به «رابطهٔ خود را با عیسی مسیح شرح دهید» به دنبال چه هستید؟`,of:`e6939ed5`,at:[`charlotte-christian:ask.questions[2]`]},{t:`آیا مراسم نیایش برای هر دانش‌آموز الزامی است؟`,of:`7ff625fb`,at:[`charlotte-christian:ask.questions[3]`,`hickory-grove-christian:ask.questions[3]`]},{t:`هر پایه به چند ساعت خدمت نیاز دارد؟ یک صفحه می‌گوید دانش‌آموزان به کسب ساعت «تشویق می‌شوند» و صفحه‌ای دیگر از «ساعت‌های خدمت الزامی مدرسه» نام می‌برد.`,of:`ac2ba319`,at:[`charlotte-christian:ask.questions[4]`]},{t:`مطالعه‌های کتاب‌مقدس Upper School چه زمانی تشکیل می‌شوند، چه کسی آن‌ها را رهبری می‌کند، و دانش‌آموز چگونه به یکی از آن‌ها می‌پیوندد؟`,of:`1d7fb7f2`,at:[`charlotte-christian:ask.questions[5]`]},{t:`Lower School و Middle School از کدام برنامهٔ درسی کتاب‌مقدس استفاده می‌کنند؟ آیا حفظ کردن آیات کتاب‌مقدس هم هست؟`,of:`5c351240`,at:[`charlotte-christian:ask.questions[6]`]},{t:`شبان مدرسه چه کاری انجام می‌دهد، و آیا خانواده‌ها می‌توانند با او دیدار کنند؟`,of:`6a615ab5`,at:[`charlotte-christian:ask.questions[7]`]},{t:`دانش‌آموزی که با ایمان مسیحی تازه آشنا شده، یا از دین دیگری است، در اینجا چگونه جا می‌افتد؟`,of:`95f84c62`,at:[`charlotte-christian:ask.questions[8]`]},{t:`آیا می‌توانیم پیش از ثبت‌نام Honor Code و Family Handbook را بخوانیم؟`,of:`9858f9f0`,at:[`charlotte-christian:ask.questions[9]`]},{t:`26 نوامبر 2026`,of:`2ffc88e3`,at:[`charlotte-christian:ask.asOf`,`hickory-grove-christian:ask.asOf`]},{t:`Hickory Grove Christian School «یکی از خدمت‌های Hickory Grove Baptist Church» است. کلیسا آن را در سال 1995 بنیان گذاشت. دانش‌آموزان هر سال کتاب‌مقدس را به‌عنوان یک درس اصلی می‌خوانند، و شبانان کلیسا در مراسم نیایش تعلیم می‌دهند.`,of:`4b2d51ae`,at:[`hickory-grove-christian:lead.strong`]},{t:`مدرسه می‌گوید: «ایمان مسیحی پایهٔ همهٔ کارهایی است که در Hickory Grove Christian School انجام می‌دهیم».`,of:`9c24d508`,at:[`hickory-grove-christian:lead.muted`]},{t:`مراسم نیایش در سال`,of:`ae6fed75`,at:[`hickory-grove-christian:stats[0].label`]},{t:`هشت صبح با مراسم جداگانه برای هر دوره و دو مراسم نیایش همهٔ مدرسه، طبق تقویم 2026–27`,of:`1d154f58`,at:[`hickory-grove-christian:stats[0].note`]},{t:`سال کتاب‌مقدس به‌عنوان درس اصلی`,of:`4e53c4e2`,at:[`hickory-grove-christian:stats[1].label`]},{t:`«از کودکستان تا پایهٔ 12»`,of:`d492bfb3`,at:[`hickory-grove-christian:stats[1].note`]},{t:`واحد کتاب‌مقدس برای فارغ‌التحصیلی`,of:`0462af41`,at:[`hickory-grove-christian:stats[2].label`]},{t:`یک درس کتاب‌مقدس در هر سال دبیرستان، از مجموع 27 واحد`,of:`eb9a213b`,at:[`hickory-grove-christian:stats[2].note`]},{t:`آیهٔ حفظ‌شده از کتاب‌مقدس`,of:`977db8d7`,at:[`hickory-grove-christian:stats[3].label`]},{t:`تا پایان دبستان، تقریباً هر هفته یک آیه`,of:`a9d6d4a3`,at:[`hickory-grove-christian:stats[3].note`]},{t:`مراسم نیایش سالی ده بار، بیشتر صبح‌های پنجشنبه، برگزار می‌شود. ابتدا دانش‌آموزان دبستان پرستش می‌کنند، سپس دانش‌آموزان دورهٔ راهنمایی و دبیرستان. شبانانی از Hickory Grove Baptist Church تعلیم می‌دهند، و دانش‌آموزان در رهبری موسیقی کمک می‌کنند.`,of:`aeef5967`,at:[`hickory-grove-christian:chapel.headline`]},{t:`مراسم نیایش دبستان`,of:`ae9892da`,at:[`hickory-grove-christian:chapel.entries[0].title`]},{t:`ساعت 8:00 صبح در روزهای مراسم نیایش. مجموعهٔ 2026–27 «زندگی مردان و زنانی از کتاب‌مقدس را دنبال می‌کند که برای خدا ایستادگی کردند».`,of:`cdc1a198`,at:[`hickory-grove-christian:chapel.entries[0].text`]},{t:`سخنرانان پاییز 2026 شامل شبانان شاگردسازی خانواده (Family Discipleship Pastors) کلیسا بودند.`,of:`f070b25c`,at:[`hickory-grove-christian:chapel.entries[0].muted`]},{t:`مراسم نیایش دورهٔ راهنمایی و دبیرستان`,of:`21c42430`,at:[`hickory-grove-christian:chapel.entries[1].title`]},{t:`ساعت 9:30 صبح، در عبادتگاه کلیسا. موضوع 2026–27 «Here I Stand» (اینجا می‌ایستم) است. دانش‌آموزان دورهٔ راهنمایی روی برگه‌های مراسم نیایش یادداشت برمی‌دارند، و دانش‌آموزان دبیرستان در دفترچهٔ Here I Stand می‌نویسند.`,of:`2b4cb461`,at:[`hickory-grove-christian:chapel.entries[1].text`]},{t:`سخنرانان پاییز 2026 شامل شبانان شاگردسازی دانش‌آموزان (Student Discipleship Pastors) کلیسا بودند. دانش‌آموزان پایه‌های 6–12 برای مراسم نیایش Honor Dress (لباس رسمی مدرسه) می‌پوشند.`,of:`2037a310`,at:[`hickory-grove-christian:chapel.entries[1].muted`]},{t:`یک مراسم نیایش شکرگزاری و یک مراسم نیایش کریسمس همهٔ مدرسه را گرد هم می‌آورند. دانش‌آموزان هنرهای نمایشی مراسم نیایش کریسمس را رهبری می‌کنند.`,of:`7eb173c0`,at:[`hickory-grove-christian:chapel.entries[2].text`]},{t:`دانش‌آموزان سال آخر در ماه آوریل یک مراسم نیایش ویژهٔ تقدیر از سال‌آخری‌ها (Senior Recognition Chapel) نیز دارند.`,of:`77e07003`,at:[`hickory-grove-christian:chapel.entries[2].muted`]},{t:`تأمل روحانی دبیرستان`,of:`0261e804`,at:[`hickory-grove-christian:chapel.entries[3].title`]},{t:`هر چهارشنبه، دانش‌آموزان دبیرستان یک تأمل روحانی دربارهٔ یکی از «سی‌وچهار شاهدی که در طول بیست قرن برای مسیح استوار ایستادند» می‌شنوند. یک معلم یا شبان هر داستان را تعریف می‌کند.`,of:`0d1d343a`,at:[`hickory-grove-christian:chapel.entries[3].text`]},{t:`تأمل روحانی دورهٔ راهنمایی`,of:`342f0c8f`,at:[`hickory-grove-christian:chapel.entries[4].title`]},{t:`معلمان هر صبح یک تأمل روحانی را رهبری می‌کنند. پیش از مدرسه، Quiet Time Cafe از 7:00 تا 7:15 صبح برای تأمل روحانی و نوشتن در دفترچهٔ روحانی باز است.`,of:`c1ee8239`,at:[`hickory-grove-christian:chapel.entries[4].text`]},{t:`Chapel Band`,of:`bbdc6ef1`,at:[`hickory-grove-christian:chapel.entries[5].title`]},{t:`دانش‌آموزان دبیرستان «در آزمون ورودی شرکت می‌کنند، تمرین می‌کنند و به شبانان پرستش ما کمک می‌کنند تا مراسم نیایشی را که دانش‌آموزان اداره می‌کنند رهبری کنند».`,of:`581f599a`,at:[`hickory-grove-christian:chapel.entries[5].text`]},{t:`Praise Team`,of:`cf0bf302`,at:[`hickory-grove-christian:chapel.entries[6].title`]},{t:`درسی در دورهٔ راهنمایی که «برای دانش‌آموزانی طراحی شده است که می‌خواهند از استعدادهای موسیقایی خود برای رهبری دیگران در پرستش استفاده کنند».`,of:`6c6a0331`,at:[`hickory-grove-christian:chapel.entries[6].text`]},{t:`خانواده‌ها می‌توانند تماشا کنند یا حضور یابند.`,of:`6bd62980`,at:[`hickory-grove-christian:chapel.note.strong`]},{t:`«هر مراسم نیایش به‌صورت زنده پخش می‌شود و در بایگانی ما ذخیره می‌شود». بازدیدکنندگان 18 سال به بالا می‌توانند از پیش ثبت‌نام کنند.`,of:`ed0a2feb`,at:[`hickory-grove-christian:chapel.note.text`]},{t:`تاریخ‌ها و ساعت‌های مراسم نیایش طبق تقویم 2026–27 مدرسه و فرم ثبت‌نام مراسم نیایش آن است.`,of:`4d3d5f47`,at:[`hickory-grove-christian:chapel.note.muted`]},{t:`کتاب‌مقدس هر سال یک درس اصلی الزامی است. در اینجا می‌بینید هر پایه چه می‌خواند، و چهار واحد کتاب‌مقدسی که دانش‌آموز دبیرستان برای فارغ‌التحصیلی لازم دارد کدام است.`,of:`7dc817f2`,at:[`hickory-grove-christian:classes.headline`]},{t:`«کلاس‌های کتاب‌مقدس در دوره‌های دبستان، راهنمایی و دبیرستان الزامی است».`,of:`03c8622c`,at:[`hickory-grove-christian:classes.intro.text`]},{t:`دانش‌آموزان دبستان «هر هفته تقریباً یک آیه از کتاب‌مقدس را حفظ می‌کنند».`,of:`7d00f8bb`,at:[`hickory-grove-christian:classes.intro.muted`]},{t:`Elementary School`,of:`444c2b2d`,at:[`hickory-grove-christian:classes.groups[0].name`]},{t:`کتاب‌مقدس هر روز`,of:`9d765c6c`,at:[`hickory-grove-christian:classes.groups[0].tally`]},{t:`کودکستان تا پایهٔ 5`,of:`edc71672`,at:[`hickory-grove-christian:classes.groups[0].rows[0].label`]},{t:`Building on the Rock، «برنامهٔ درسی جهان‌بینی کتاب‌مقدسی و مرور کتاب‌مقدس». «هر روز با کلام خدا، تأملی روحانی از سوی معلم و دعا آغاز می‌شود».`,of:`0008928c`,at:[`hickory-grove-christian:classes.groups[0].rows[0].detail`]},{t:`Kingdom Builders`,of:`9a94434e`,at:[`hickory-grove-christian:classes.groups[0].rows[1].label`]},{t:`کلاسی ویژه با «درس‌هایی بر پایهٔ کتاب‌مقدس دربارهٔ موضوعاتی مانند ارتباط، حل اختلاف، حل مسئله و روحیهٔ جوانمردی در ورزش».`,of:`34246ae1`,at:[`hickory-grove-christian:classes.groups[0].rows[1].detail`]},{t:`هر سال یک کلاس کتاب‌مقدس`,of:`3ba77ed2`,at:[`hickory-grove-christian:classes.groups[1].tally`]},{t:`Building on the Rock`,of:`82cdd00e`,at:[`hickory-grove-christian:classes.groups[1].rows[0].label`]},{t:`جهان‌بینی مسیحی، از Summit Ministries.`,of:`61361a88`,at:[`hickory-grove-christian:classes.groups[1].rows[0].detail`]},{t:`Walking in Truth`,of:`2e76621e`,at:[`hickory-grove-christian:classes.groups[1].rows[1].label`]},{t:`باورهای اصلی مسیحیت را با اسلام، طبیعت‌گرایی و معنویت نوین مقایسه می‌کند. از Summit Ministries.`,of:`c3bd391f`,at:[`hickory-grove-christian:classes.groups[1].rows[1].detail`]},{t:`Light Bearers`,of:`77453ec1`,at:[`hickory-grove-christian:classes.groups[1].rows[2].label`]},{t:`به دانش‌آموزان کمک می‌کند «درک کنند چگونه می‌توانند جهان‌بینی مسیحی خود را در فرهنگی پسامسیحی زندگی کنند». از Summit Ministries.`,of:`56bce3dc`,at:[`hickory-grove-christian:classes.groups[1].rows[2].detail`]},{t:`درس‌های اختیاری ایمان و رهبری`,of:`427a5e5d`,at:[`hickory-grove-christian:classes.groups[1].rows[3].label`]},{t:`درس‌ها شامل Becoming a Young Man of God و Becoming a Young Woman of God (پایه‌های 7–8)، Student on Mission، و Christian Leadership برای دانش‌آموزان منتخب پایهٔ 8 است.`,of:`120cc5ee`,at:[`hickory-grove-christian:classes.groups[1].rows[3].detail`]},{t:`High School`,of:`8ab05d33`,at:[`hickory-grove-christian:classes.groups[2].name`]},{t:`برای فارغ‌التحصیلی 4 واحد کتاب‌مقدس`,of:`f3ba47fd`,at:[`hickory-grove-christian:classes.groups[2].tally`]},{t:`سطح آماده‌سازی دانشگاهی یا افتخاری (honors). دانش‌آموزان «کل کتاب‌مقدس را از راه مضمون‌های کلی مرور می‌کنند».`,of:`f8d1174b`,at:[`hickory-grove-christian:classes.groups[2].rows[0].detail`]},{t:`سطح آماده‌سازی دانشگاهی یا افتخاری. کتاب‌های عهد جدید، جهان آن و زندگی مسیح.`,of:`b2b63ff9`,at:[`hickory-grove-christian:classes.groups[2].rows[1].detail`]},{t:`Christian Apologetics`,of:`8e467286`,at:[`hickory-grove-christian:classes.groups[2].rows[2].label`]},{t:`سطح آماده‌سازی دانشگاهی یا افتخاری. دانش‌آموزان «شواهد منطقی، فلسفی، تاریخی و علمی ایمان مسیحی» را می‌آموزند. گزینهٔ دیگر Honors Introduction to Philosophy است.`,of:`13dd27c3`,at:[`hickory-grove-christian:classes.groups[2].rows[2].detail`]},{t:`Systematic Theology`,of:`2723738e`,at:[`hickory-grove-christian:classes.groups[2].rows[3].label`]},{t:`سطح آماده‌سازی دانشگاهی یا افتخاری. دانش‌آموزان «درک خود را از آموزه‌هایی که برای ایمان مسیحی راست‌کیش ضروری‌اند استوار می‌کنند». گزینهٔ دیگر Honors Introduction to Ethics است.`,of:`e795a1ff`,at:[`hickory-grove-christian:classes.groups[2].rows[3].detail`]},{t:`Introduction to Bible`,of:`167dd6e0`,at:[`hickory-grove-christian:classes.groups[2].rows[4].label`]},{t:`درسی که «برای دانش‌آموزانی توصیه می‌شود که هرگز در مدرسهٔ مسیحی درس نخوانده‌اند یا در HGCS تازه‌وارد هستند». ثبت‌نام در آن با توصیهٔ مدرسه است.`,of:`5fc47c09`,at:[`hickory-grove-christian:classes.groups[2].rows[4].detail`]},{t:`درس‌های افتخاری و واحد دانشگاهی.`,of:`85df5dd5`,at:[`hickory-grove-christian:classes.note.strong`]},{t:`پنج درس افتخاری کتاب‌مقدس، درس‌های ثبت‌نام دوگانه (dual enrollment، یعنی درس‌هایی که واحد دانشگاهی هم می‌دهند) از طریق Judson College هستند، «برنامهٔ دورهٔ کارشناسی Southeastern Baptist Theological Seminary (SEBTS)».`,of:`aa231f5b`,at:[`hickory-grove-christian:classes.note.text`]},{t:`دانش‌آموزان برنامهٔ غوطه‌وری در زبان اسپانیایی (Spanish Immersion) در دورهٔ راهنمایی، کتاب‌مقدس را به زبان اسپانیایی می‌خوانند.`,of:`d66b9c75`,at:[`hickory-grove-christian:classes.note.muted`]},{t:`جایی که دانش‌آموزان در گروه‌های کوچک‌تر دربارهٔ ایمان گفت‌وگو می‌کنند: گروه‌های ماهانهٔ دورهٔ راهنمایی و گروه‌های دبیرستان به رهبری معلمان.`,of:`ea4ea9d7`,at:[`hickory-grove-christian:groups.headline`]},{t:`Grove Groups`,of:`d6c20d68`,at:[`hickory-grove-christian:groups.entries[0].title`]},{t:`«در نخستین پنجشنبهٔ هر ماه»، دانش‌آموزان بر اساس پایه گرد هم می‌آیند تا از «زندگی شهیدان، مبلغان و مربیان» بیاموزند، و سپس به گروه‌های کوچک شاگردسازی تقسیم می‌شوند.`,of:`8194ca24`,at:[`hickory-grove-christian:groups.entries[0].text`]},{t:`گروه‌های شاگردسازی (D-groups)`,of:`5887b986`,at:[`hickory-grove-christian:groups.entries[1].title`]},{t:`«هر دانش‌آموز دبیرستان در یک گروه کوچک شاگردسازی به رهبری یک معلم قرار می‌گیرد». گروه‌ها بیشتر پنجشنبه‌ها، در وقت میانهٔ روز Club Flex، تشکیل می‌شوند.`,of:`98ff950b`,at:[`hickory-grove-christian:groups.entries[1].text`]},{t:`یک شبان دانش‌آموزان در مدرسه`,of:`e2c19d02`,at:[`hickory-grove-christian:groups.entries[2].title`]},{t:`«شبان شاگردسازی دانش‌آموزان» کلیسا «در مدرسه حضور دارد و برای گفت‌وگوهای رودررو با دانش‌آموزان در دسترس است».`,of:`ec0c5403`,at:[`hickory-grove-christian:groups.entries[2].text`]},{t:`Christian Leadership`,of:`7dddde73`,at:[`hickory-grove-christian:groups.entries[3].title`]},{t:`درسی برای دانش‌آموزان منتخب پایهٔ 8، که «از آنان انتظار می‌رود متعهد شوند در تمام سال تحصیلی به‌عنوان رهبران مدرسه خدمت کنند».`,of:`439d6477`,at:[`hickory-grove-christian:groups.entries[3].text`]},{t:`تیم‌های ورزشی هم.`,of:`4f01fc7b`,at:[`hickory-grove-christian:groups.note.strong`]},{t:`یکی از اهداف برنامهٔ ورزشی «شاگردسازی ورزشکاران» است: «می‌کوشیم در تیم‌هایمان شاگردسازی عالی داشته باشیم».`,of:`ef4fa25a`,at:[`hickory-grove-christian:groups.note.text`]},{t:`مأموریت و چشم‌انداز مدرسه، باورهایی که فهرست می‌کند، و نتایجی که برای هر دانش‌آموز امید دارد، به بیان خود مدرسه.`,of:`e021d1dc`,at:[`hickory-grove-christian:beliefs.headline`]},{t:`«Hickory Grove Christian School دانش‌آموزان را از راه جهان‌بینی کتاب‌مقدسی شاگرد می‌سازد و آنان را در درس، ورزش و هنر پرورش می‌دهد تا به خدا متعهد، به مأموریت پیوسته و در مسیح حکیم باشند، تا او را بشناسند و او را بشناسانند».`,of:`5f8ff62b`,at:[`hickory-grove-christian:beliefs.mission`]},{t:`هر حقیقتی حقیقت خداست، و هر درسی باید از دریچهٔ جهان‌بینی کتاب‌مقدسی آموزش داده شود.`,of:`36d2ef5b`,at:[`hickory-grove-christian:beliefs.tenets[0]`]},{t:`آموزش مسیحی تلاشی مشترک میان مدرسه، خانه، Hickory Grove Baptist Church و بدن گسترده‌تر مسیح است.`,of:`f6f84166`,at:[`hickory-grove-christian:beliefs.tenets[1]`]},{t:`آموزش مسیحی باید چشم‌اندازی ابدی داشته باشد و بر نجات و شاگردسازی نسل آینده متمرکز باشد.`,of:`8c70a21c`,at:[`hickory-grove-christian:beliefs.tenets[2]`]},{t:`موفقیت در HGCS نه‌تنها با رهبری، برتری و درستکاری دانش‌آموزان، بلکه بیش از همه با تعهدی همیشگی به عیسی مسیح سنجیده می‌شود.`,of:`0daba68d`,at:[`hickory-grove-christian:beliefs.tenets[3]`]},{t:`محیطی پرچالش در درس، ورزش و هنر، دانش‌آموزان را به‌طور کامل برای چالش‌های پیش رویشان آماده می‌کند.`,of:`65c91b53`,at:[`hickory-grove-christian:beliefs.tenets[4]`]},{t:`دانش‌آموزان به شیوه‌های گوناگون یاد می‌گیرند، پس معلمان ما از راهبردهای آموزشی گوناگونی برای پشتیبانی از هر یادگیرنده استفاده می‌کنند.`,of:`afda4e27`,at:[`hickory-grove-christian:beliefs.tenets[5]`]},{t:`هر دانش‌آموز به صورت خدا آفریده شده است، با نیازهای روحانی، تحصیلی، جسمی، ذهنی و عاطفی منحصربه‌فرد.`,of:`3e390e3c`,at:[`hickory-grove-christian:beliefs.tenets[6]`]},{t:`متعهد به خدا`,of:`38f9009c`,at:[`hickory-grove-christian:beliefs.outcomes[0].name`]},{t:`سرسپرده به خداوند، با محبت‌هایی که به‌درستی سامان یافته‌اند`,of:`6a42cc80`,at:[`hickory-grove-christian:beliefs.outcomes[0].text`]},{t:`پیوسته به مأموریت`,of:`86faef7c`,at:[`hickory-grove-christian:beliefs.outcomes[1].name`]},{t:`پیوسته به بدن مسیح در مأموریتی مشترک`,of:`5d2fac4e`,at:[`hickory-grove-christian:beliefs.outcomes[1].text`]},{t:`حکیم در مسیح`,of:`5686ade5`,at:[`hickory-grove-christian:beliefs.outcomes[2].name`]},{t:`تشخیص‌دهنده میان حکمت کتاب‌مقدسی خدا و حکمت دنیا`,of:`0148d0ab`,at:[`hickory-grove-christian:beliefs.outcomes[2].text`]},{t:`یکی از خدمت‌های Hickory Grove Baptist Church.`,of:`675ad5ae`,at:[`hickory-grove-christian:beliefs.note.strong`]},{t:`چشم‌انداز آن: «شناختن مسیح و شناساندن او از راه آموزش مسیحی».`,of:`20f3e7c2`,at:[`hickory-grove-christian:beliefs.note.text`]},{t:`آیهٔ مدرسه Matthew 6:33 است. مدرسه اعتباربخشی دوگانه از Cognia و Association of Christian Schools International (ACSI) دارد.`,of:`1145ea45`,at:[`hickory-grove-christian:beliefs.note.muted`]},{t:`فهرست بازبینی هر پایه یک «Personal Recommendation form» (فرم توصیه‌نامهٔ شخصی) از شبان خانواده را در بر دارد. برای دورهٔ راهنمایی و دبیرستان، این فرم «از شبان دانش‌آموز/خانواده» است.`,of:`3492170f`,at:[`hickory-grove-christian:families.groups[0].rows[0].detail`]},{t:`«مصاحبه با خانواده فرصتی است برای در میان گذاشتن مأموریت، چشم‌انداز و اعتقادنامه، و برای سنجیدن اینکه آیا HGCS برای خانوادهٔ شما مناسب است یا نه».`,of:`7e1fcf3b`,at:[`hickory-grove-christian:families.groups[0].rows[1].detail`]},{t:`پرسش‌نامهٔ دانش‌آموز`,of:`70bc4595`,at:[`hickory-grove-christian:families.groups[0].rows[2].label`]},{t:`متقاضیان پایه‌های 4–12 یک Student Questionnaire (پرسش‌نامهٔ دانش‌آموز) را پر می‌کنند. پرسش‌های آن در سایت عمومی نیست.`,of:`58072980`,at:[`hickory-grove-christian:families.groups[0].rows[2].detail`]},{t:`اعضای کلیسا زودتر درخواست می‌دهند`,of:`62834a83`,at:[`hickory-grove-christian:families.groups[0].rows[3].label`]},{t:`درخواست‌ها در 2 نوامبر 2026 برای اعضای کلیسا، دانش‌آموزان Early Education Center (مرکز آموزش خردسالان) و خواهران و برادرانشان باز شد، و در 16 نوامبر برای همهٔ خانواده‌های جدید.`,of:`ff1eefee`,at:[`hickory-grove-christian:families.groups[0].rows[3].detail`]},{t:`صفحه‌های عمومی نمی‌گویند که آیا پدر یا مادر باید مسیحی یا عضو کلیسایی باشد. با این حال، فرم ابراز علاقهٔ پیش‌دبستانی Mallard Creek دربارهٔ کلیسای خانواده و ایمان والدین می‌پرسد.`,of:`90bc5e19`,at:[`hickory-grove-christian:families.groups[0].rows[4].detail`]},{t:`پذیرفتن اعتقادنامه`,of:`4d0e62a1`,at:[`hickory-grove-christian:families.groups[0].rows[5].label`]},{t:`صفحه‌های عمومی نمی‌گویند که آیا خانواده‌ها آن را امضا می‌کنند یا نه.`,of:`78c021b6`,at:[`hickory-grove-christian:families.groups[0].rows[5].detail`]},{t:`هر سال الزامی است.`,of:`b2052a02`,at:[`hickory-grove-christian:families.groups[1].rows[0].detail`]},{t:`Honor Code (منشور شرافت)`,of:`44cd5ffc`,at:[`hickory-grove-christian:families.groups[1].rows[1].label`]},{t:`«هر دانش‌آموز دبیرستان Student Honor Code ما را امضا می‌کند؛ پیمانی که بر پایهٔ سه نتیجهٔ مورد انتظار ما از دانش‌آموزان سامان یافته است».`,of:`32678a3d`,at:[`hickory-grove-christian:families.groups[1].rows[1].detail`]},{t:`پوشش مراسم نیایش`,of:`2f4b2596`,at:[`hickory-grove-christian:families.groups[1].rows[2].label`]},{t:`«Honor Dress برای همهٔ برنامه‌های مراسم نیایش در پایه‌های 6-12 و در برخی رویدادهای ویژه الزامی است».`,of:`94b46255`,at:[`hickory-grove-christian:families.groups[1].rows[2].detail`]},{t:`آگهی استخدام کسی را می‌خواهد که «مسیحی متعهد و موافق با اعتقادنامهٔ مدرسه» و «فعال در یک کلیسای محلی معتقد به کتاب‌مقدس» باشد.`,of:`13cc08e6`,at:[`hickory-grove-christian:families.note.text`]},{t:`مدرسه Parent-Student Handbook (راهنمای والدین و دانش‌آموزان) و فرم درخواست آنلاین خود را پشت صفحهٔ ورود خانواده‌ها نگه می‌دارد.`,of:`80ae7348`,at:[`hickory-grove-christian:families.note.muted`]},{t:`دانش‌آموزان سال آخر هر سال به یک سفر بشارتی به جمهوری دومینیکن می‌روند، و همهٔ مدرسه هر سه ماه یک بار برای یک هدف خیریه کمک می‌کند.`,of:`c319faa6`,at:[`hickory-grove-christian:service.headline`]},{t:`سفر بشارتی سال آخر`,of:`33553cb2`,at:[`hickory-grove-christian:service.entries[0].title`]},{t:`«دانش‌آموزان سال آخر ما هر سال با هم در یک سفر بشارتی به جمهوری دومینیکن خدمت می‌کنند». سفر 2026–27 در ژانویهٔ 2027 است.`,of:`e89f1c2f`,at:[`hickory-grove-christian:service.entries[0].text`]},{t:`هفتهٔ خدمت دبیرستان (Mission Week)`,of:`2ac49c4f`,at:[`hickory-grove-christian:service.entries[1].title`]},{t:`«در مدتی که دانش‌آموزان سال آخر در سفرند، بقیهٔ دبیرستان از راه Mission Week به جامعهٔ محلی خدمت می‌کنند».`,of:`e298e406`,at:[`hickory-grove-christian:service.entries[1].text`]},{t:`جمع‌آوری کمک بشارتی هر سه ماه`,of:`d7df1e39`,at:[`hickory-grove-christian:service.entries[2].title`]},{t:`«هر سه ماه یک بار، خانوادهٔ مدرسهٔ ما برای پشتیبانی از یک خدمت یا هدف محلی کمک می‌کند». هدف‌های نام‌برده شامل XChange، خدمتی از کلیسا برای رهایی از اعتیاد؛ Operation Christmas Child؛ و یک Baby Bottle Drive (جمع‌آوری کمک در شیشه‌شیر) «در پشتیبانی از حرمت زندگی انسان» است.`,of:`421bf44c`,at:[`hickory-grove-christian:service.entries[2].text`]},{t:`HGBC Food Pantry`,of:`2e9ac33b`,at:[`hickory-grove-christian:service.entries[3].title`]},{t:`دانش‌آموزان Spanish Immersion «هر هفته، هنگامی که شبانان ما انجیل را با جامعهٔ ما در میان می‌گذارند، در نقش مترجم خدمت می‌کنند». آزمایشگاه آکواپونیک دبیرستان «برای HG Food Pantry غذا پرورش می‌دهد».`,of:`5db014a7`,at:[`hickory-grove-christian:service.entries[3].text`]},{t:`Student on Mission`,of:`23157b7b`,at:[`hickory-grove-christian:service.entries[4].title`]},{t:`درسی در دورهٔ راهنمایی که «بررسی می‌کند خدا در سراسر جهان چه می‌کند و دانش‌آموزان چگونه می‌توانند به شارلوت خدمت کنند».`,of:`84aa6016`,at:[`hickory-grove-christian:service.entries[4].text`]},{t:`Global Missions & Language Certificate`,of:`80313ab8`,at:[`hickory-grove-christian:service.entries[5].title`]},{t:`دانش‌آموزان آن را با سه واحد زبان خارجی، درس‌های افتخاری کتاب‌مقدس، «دست‌کم یک سفر بشارتی بین‌المللی» و یک کارورزی یا دورهٔ عملی بشارتی به دست می‌آورند.`,of:`b39f9bee`,at:[`hickory-grove-christian:service.entries[5].text`]},{t:`فهرست درس‌ها یک شرط دیگر هم می‌افزاید: «عضو فعال کلیسایی هم‌باور باشد، که با یک توصیه‌نامهٔ مثبت از یک شبان، ترجیحاً شبان نوجوانان خود دانش‌آموز، تأیید شود».`,of:`ec79c40a`,at:[`hickory-grove-christian:service.entries[5].muted`]},{t:`خانواده‌های میزبان`,of:`08de32bd`,at:[`hickory-grove-christian:service.entries[6].title`]},{t:`خانواده‌های کلیسا و خانواده‌های مدرسه می‌توانند میزبان یک دانش‌آموز بین‌المللی باشند. مدرسه این را «بشارت وارونه» می‌نامد.`,of:`ff765539`,at:[`hickory-grove-christian:service.entries[6].text`]},{t:`خدمت فراتر از شارلوت.`,of:`ccf8f5b9`,at:[`hickory-grove-christian:service.note.strong`]},{t:`مدرسه از «تلاش‌های خدمت‌رسانی بین‌المللی در جمهوری دومینیکن، اکوادور، هائیتی و کنیا» نام می‌برد.`,of:`69d038ac`,at:[`hickory-grove-christian:service.note.text`]},{t:`صفحه‌های مدرسه هیچ الزامی برای ساعت خدمت ذکر نمی‌کنند.`,of:`5de87f7f`,at:[`hickory-grove-christian:service.note.muted`]},{t:`شبانانی از Hickory Grove Baptist Church در مراسم نیایش تعلیم می‌دهند و نشست‌های والدین را رهبری می‌کنند. مدرسه هیچ کشیش ویژهٔ خود (chaplain) را فهرست نمی‌کند.`,of:`91c82d15`,at:[`hickory-grove-christian:staff.headline`]},{t:`شبان ارشد، Hickory Grove Baptist Church؛ عضو هیئت مشورتی`,of:`62f34cd6`,at:[`hickory-grove-christian:staff.people[0].role`]},{t:`شبان شاگردسازی دانش‌آموزان، Hickory Grove Baptist Church`,of:`29d78e88`,at:[`hickory-grove-christian:staff.people[1].role`,`hickory-grove-christian:staff.people[2].role`]},{t:`شبان شاگردسازی خانواده، Hickory Grove Baptist Church`,of:`f6d67519`,at:[`hickory-grove-christian:staff.people[3].role`,`hickory-grove-christian:staff.people[4].role`]},{t:`سرپرست گروه کتاب‌مقدس، دبیرستان`,of:`a7f858b3`,at:[`hickory-grove-christian:staff.people[5].role`]},{t:`کتاب‌مقدس دورهٔ راهنمایی، تربیت بدنی`,of:`21497841`,at:[`hickory-grove-christian:staff.people[6].role`]},{t:`معلمان و رهبران تأمل‌های روحانی چهارشنبه را به نوبت برگزار می‌کنند.`,of:`c96e81fc`,at:[`hickory-grove-christian:staff.note.strong`]},{t:`سخنرانان پاییز 2026 شامل رئیس مدرسه و مدیر دبیرستان بودند.`,of:`78ceaec7`,at:[`hickory-grove-christian:staff.note.muted`]},{t:`یک نشست برای والدین در روزهای مراسم نیایش، مرورهایی از هر مراسم نیایش و تأمل روحانی برای خانه، و یک گروه دعای ماهانه.`,of:`f368223d`,at:[`hickory-grove-christian:parents.headline`]},{t:`Lions Connect`,of:`d035b4a2`,at:[`hickory-grove-christian:parents.entries[0].title`]},{t:`«Lions Connect در صبح‌های مراسم نیایش، میان مراسم نیایش دبستان و مراسم نیایش دورهٔ راهنمایی و دبیرستان، برگزار می‌شود تا بتوانید همراه فرزندتان پرستش کنید و برای هر دو بمانید». شبانان کلیسا آن را رهبری می‌کنند، ساعت 9:00 صبح.`,of:`237fa7e7`,at:[`hickory-grove-christian:parents.entries[0].text`]},{t:`موضوع‌های پاییز 2026 «Because I Told You So» (چون من گفتم) و «Hard Providences» (مشیت‌های دشوار) بودند.`,of:`30748e72`,at:[`hickory-grove-christian:parents.entries[0].muted`]},{t:`Chapel at Home`,of:`303afda6`,at:[`hickory-grove-christian:parents.entries[1].title`]},{t:`پس از هر مراسم نیایش، خانواده‌ها مروری دریافت می‌کنند که پیام، آیه‌های کتاب‌مقدس آن و «چند پرسش برای گفت‌وگو با فرزندتان» را در بر دارد. یک نسخه برای دبستان و یک نسخه برای دورهٔ راهنمایی و دبیرستان هست.`,of:`119beb08`,at:[`hickory-grove-christian:parents.entries[1].text`]},{t:`مرور تأمل‌های روحانی`,of:`d198ee5d`,at:[`hickory-grove-christian:parents.entries[2].title`]},{t:`مروری یک‌صفحه‌ای از هر تأمل روحانی چهارشنبهٔ دبیرستان، «تا بتوانید سر شام یا در ماشین دربارهٔ آن از فرزندتان بپرسید».`,of:`8b520ec0`,at:[`hickory-grove-christian:parents.entries[2].text`]},{t:`Lions in Prayer`,of:`0b8e5ea6`,at:[`hickory-grove-christian:parents.entries[3].title`]},{t:`«والدین ماهی یک بار گرد هم می‌آیند تا برای دانش‌آموزان، کارکنان و مدرسهٔ ما دعا کنند». نشست‌ها ساعت 8:00 صبح در نخستین دوشنبهٔ هر ماه برگزار می‌شوند.`,of:`beaefa22`,at:[`hickory-grove-christian:parents.entries[3].text`]},{t:`Parent Teacher Fellowship (انجمن والدین و معلمان).`,of:`b1101883`,at:[`hickory-grove-christian:parents.note.strong`]},{t:`«خود را انجمن مشارکت (fellowship) می‌نامیم، چون ایماندارانی هستیم که در پیشبرد آموزش ملکوتی (Kingdom Education) با هم متحدیم».`,of:`09ed8c22`,at:[`hickory-grove-christian:parents.note.text`]},{t:`تماس: Cynthia Sampson، cynthiasampson@hgchristian.org.`,of:`2bfea94f`,at:[`hickory-grove-christian:parents.note.muted`]},{t:`دوازده پرسش برای همراه بردن به بازدید از مدرسه. هر پرسش به چیزی می‌پردازد که صفحه‌های عمومی مدرسه بی‌پاسخ می‌گذارند یا به دو شکل می‌گویند.`,of:`44bce139`,at:[`hickory-grove-christian:ask.headline`]},{t:`فرم توصیه‌نامهٔ شبان چه می‌پرسد؟ اگر خانوادهٔ ما شبانی نداشته باشد چه؟`,of:`b242ce9b`,at:[`hickory-grove-christian:ask.questions[1]`]},{t:`آیا می‌توانیم اعتقادنامه‌ای را که در مصاحبه با خانواده ارائه می‌شود بخوانیم؟ آیا خانواده‌ها آن را امضا می‌کنند؟`,of:`e9e95fd8`,at:[`hickory-grove-christian:ask.questions[2]`]},{t:`مراسم نیایش هر چند وقت یک بار برگزار می‌شود؟ یک صفحه می‌گوید ماهی یک بار، و تقویم 2026–27 دو مراسم در ماه مارس دارد.`,of:`bce6454c`,at:[`hickory-grove-christian:ask.questions[4]`]},{t:`گروه‌های شاگردسازی دبیرستان هر چند وقت یک بار تشکیل می‌شوند؟ یک صفحه می‌گوید چند بار در ماه، و صفحه‌ای دیگر می‌گوید بیشتر پنجشنبه‌ها.`,of:`b8ed44ef`,at:[`hickory-grove-christian:ask.questions[5]`]},{t:`آیا همهٔ دانش‌آموزان سال آخر به سفر بشارتی جمهوری دومینیکن می‌روند، و آیا هزینهٔ آن بخشی از شهریه است؟`,of:`895c399b`,at:[`hickory-grove-christian:ask.questions[6]`]},{t:`دانش‌آموزی که در پایهٔ 10، 11 یا 12 به مدرسه می‌پیوندد به چند واحد کتاب‌مقدس نیاز دارد؟`,of:`a7b381c8`,at:[`hickory-grove-christian:ask.questions[7]`]},{t:`آیا برای هیچ پایه‌ای اردوی روحانی برگزار می‌شود؟`,of:`6423bdb4`,at:[`hickory-grove-christian:ask.questions[8]`]},{t:`آیا ساعت خدمت الزامی است؟`,of:`65648d57`,at:[`hickory-grove-christian:ask.questions[9]`]},{t:`آیا دانش‌آموزان دبستان و دورهٔ راهنمایی هم Honor Code را امضا می‌کنند؟`,of:`e43e6b9e`,at:[`hickory-grove-christian:ask.questions[10]`]},{t:`آیا می‌توانیم پیش از ثبت‌نام Parent-Student Handbook را بخوانیم؟`,of:`65b596cb`,at:[`hickory-grove-christian:ask.questions[11]`]}]};export{e as default};